"""Money parsing."""
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

TWO_PLACES = Decimal("0.01")


def parse_amount(text):
    """Parse a ledger amount into a Decimal.

    Accepted forms, surrounding whitespace ignored:

    * plain or signed decimals: "12.50", "-12.50", "+12.50", "7"
    * thousands separators: "1,234.50"
    * accounting negatives in parentheses: "(12.50)" means -12.50

    The result always carries exactly two decimal places, so "7" parses to
    Decimal("7.00"). Anything else raises ValueError.
    """
    if not isinstance(text, str):
        raise ValueError(f"amount must be a string, got {type(text).__name__}")
    s = text.strip()
    negative = False
    if len(s) >= 2 and s[0] == "(" and s[-1] == ")":
        negative = True
        s = s[1:-1].strip()
    if "," in s:
        groups = s.split(",")
        # first group (integer part before first comma): no dot, 1-3 digits
        if "." in groups[0] or not (1 <= len(groups[0]) <= 3):
            raise ValueError(f"invalid amount: {text!r}")
        # middle groups: exactly 3 digits, no dot
        if any("." in g or len(g) != 3 for g in groups[1:-1]):
            raise ValueError(f"invalid amount: {text!r}")
        # last group: may be the decimal part, but at most one dot
        if groups[-1].count(".") > 1:
            raise ValueError(f"invalid amount: {text!r}")
        s = s.replace(",", "")
    try:
        value = Decimal(s)
    except InvalidOperation:
        raise ValueError(f"invalid amount: {text!r}")
    if not value.is_finite():
        raise ValueError(f"invalid amount: {text!r}")
    if negative:
        value = -value
    return value.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)
